setup.sql:
CREATE OR REPLACE PACKAGE ${owner}.D7_PKG_${run_id} AS
  FUNCTION TWICE(P_N NUMBER) RETURN NUMBER;
  PROCEDURE PING;
END;

CREATE OR REPLACE PACKAGE BODY ${owner}.D7_PKG_${run_id} AS
  FUNCTION TWICE(P_N NUMBER) RETURN NUMBER IS
  BEGIN
    RETURN P_N * 2;
  END;
  PROCEDURE PING IS BEGIN EXECUTE IMMEDIATE 'SELECT 1 FROM DUAL'; END;
END;
